// Category A — a navigation drawn as a Button. Behaviour is React Aria's `Link` (a real <a>: role link,
// Enter follows it, the browser can open it in a new tab); the look is Button's own `.sd-button`, read
// from `Button.css`, so there is one Button look and no second copy of it. RAC's Link emits the same
// state attributes Button.css keys on (`data-hovered`, `data-pressed`, `data-focus-visible`,
// `data-disabled`), so every state rule applies unchanged. A separate component rather than
// `Link variant="button"`: Link's `variant` already names how its underline draws, so Button's
// variant and size would arrive as a second vocabulary on the same prop, and the root class would
// swap by prop value, which component-contract.md §6 rule 3 forbids.
import { Link as AriaLink, Provider, Text, TextContext } from "react-aria-components";
import type { LinkProps as AriaLinkProps } from "react-aria-components";
import { Children } from "react";
import type { ReactNode, Ref } from "react";
import type { ButtonBaseProps } from "./Button";
import { roleSize } from "./controlSize";
import "./Button.css";

export interface LinkButtonProps extends Omit<AriaLinkProps, "className" | "href" | "children"> {
  /**
   * Visual variant, Button's ladder (`prop-usage-contract.md` § Variant): the page's forward
   * destination is `primary`, every other worded one `secondary`.
   *
   * @default "primary"
   */
  variant?: Exclude<ButtonBaseProps["variant"], "provider">;
  /**
   * Size axis, Button's control-height ladder.
   *
   * @default "medium"
   */
  size?: ButtonBaseProps["size"];
  /** Where it goes. Required: without it React Aria renders a `<span role="link">`, not an anchor. */
  href: string;
  /** The visible label. Text is wrapped for Button's text inset; with an icon, wrap the words in `<Text>`. */
  children: ReactNode;
  /** Additional class (optional). sd-button is always preserved. */
  className?: string;
  /** Forwarded to the underlying <a> DOM node. */
  ref?: Ref<HTMLAnchorElement>;
}

/** Button's own test (Button.tsx): only a run of strings and numbers is auto-wrapped in one `<Text>`. */
function isTextOnly(content: ReactNode): boolean {
  const parts = Children.toArray(content);
  return parts.length > 0 && parts.every((p) => typeof p === "string" || typeof p === "number");
}

export function LinkButton({
  variant = "primary",
  size = "medium",
  children,
  className,
  ...props
}: LinkButtonProps) {
  return (
    <AriaLink
      {...props}
      data-variant={variant}
      data-size={size}
      className={
        className
          ? `sd-button sd-type-label-${roleSize(size)} ${className}`
          : `sd-button sd-type-label-${roleSize(size)}`
      }
    >
      {/* Button's label box: above the ::after state layer, and the text inset on the words only. */}
      <span className="sd-button__label">
        <Provider values={[[TextContext, { className: "sd-button__text" }]]}>
          {isTextOnly(children) ? <Text>{children}</Text> : children}
        </Provider>
      </span>
    </AriaLink>
  );
}
